list_countries.code:
const response = await client.countries.listCountries({search: 'aus'});
for (const country of response.map.countries) {
    console.log(country.id, country.code, country.name, country.state_count);
}
console.log(response.map.pagination.total);

get_country.code:
const response = await client.countries.getCountry('AU');
const country = response.map.country;
console.log(country.id, country.name, country.state_count, country.default);

list_country_states.code:
const response = await client.countries.listCountryStates('AU', {limit: 3});
console.log(response.map.country.name);
for (const state of response.map.states) {
    console.log(state.id, state.code, state.name);
}
console.log(response.map.pagination.total, response.map.pagination.has_next);

get_country_state.code:
const response = await client.countries.getCountryState('AU', 'VIC');
const state = response.map.state;
console.log(response.map.country.code, state.id, state.name, state.active);
